<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const username=ref(''),password=ref(''),error=ref(''),loading=ref(false),router=useRouter(),auth=useAuthStore(); async function submit(){loading.value=true;error.value='';try{await auth.login(username.value,password.value);await router.replace('/');}catch{error.value='登录失败，请检查账号、密码或服务状态。';}finally{loading.value=false;}}</script><template><main class="login"><el-card><h1>医院数字化平台</h1><p>管理后台</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="username" autocomplete="username" placeholder="账号"/></el-form-item><el-form-item><el-input v-model="password" type="password" show-password autocomplete="current-password" placeholder="密码"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button native-type="submit" type="primary" :loading="loading" class="full">登录</el-button></el-form></el-card></main></template>
